window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0d58b7b08be8d734"]={"versions": [{"id": "FIG-0d58b7b08be8d734", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur internen Zählerverwaltung (Inkrementierung und Überlaufbehandlung) innerhalb der AUTOSAR E2E-Protokollspezifikation (Classic &amp; Adaptive Platform). Das Diagramm spezifiziert den sequenziellen Steuerfluss zur Aktualisierung des Zustandszählers eines E2E-Überwachungsstatus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node) zur Auslösung der Zähleraktualisierung\n</li><li>Entscheidungsknoten (Decision Node) zur Prüfung der Zählergrenze (<code>State-&gt;Counter ?</code>)\n</li><li>Aktionszustand <code>State-&gt;Counter ++</code> (Inkrementieren des Zählers)\n</li><li>Aktionszustand <code>State-&gt; Counter = 0</code> (Zurücksetzen des Zählers bei Erreichen der Obergrenze)\n</li><li>Zusammenführungsknoten (Merge Node)\n</li><li>Endknoten (Activity Final Node)\n</li><li>Zustandsvariable <code>State-&gt;Counter</code> als Teil der Zustandsstruktur <code>State</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf startet am Initialknoten.\n</li><li>An der Verzweigung wird die Bedingung bezüglich des aktuellen Zählerwerts <code>State-&gt;Counter</code> geprüft.\n</li><li>Ergibt die Auswertung <code>[TRUE]</code>, wird der linke Pfad durchlaufen und <code>State-&gt;Counter ++</code> ausgeführt.\n</li><li>Ergibt die Auswertung <code>[FALSE]</code>, wird der rechte Pfad durchlaufen und <code>State-&gt; Counter = 0</code> ausgeführt.\n</li><li>Beide Ausführungspfade vereinigen sich im Merge-Knoten und führen direkt zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine elementare Zähler-Inkrementierung mit zyklischem Überlauf auf 0. Implementierer müssen sicherstellen, dass die Grenze des Zählerbereichs exakt der Spezifikation des jeweiligen E2E-Profils entspricht und atomar auf der Zustandsstruktur <code>State</code> aktualisiert wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dce6a37ceea2173d", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Berechnung des Zählerdifferenzwerts (<code>DeltaCounter</code>) bei Empfang einer E2E-geschützten Botschaft innerhalb der AUTOSAR E2E-Protokollspezifikation. Es stellt den normativen Berechnungsalgorithmus inklusive Modulo-16-Überlaufkorrektur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionszustand <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> (Berechnung der Rohdifferenz)\n</li><li>Entscheidungsknoten <code>(sint8) DeltaCounter &lt; 0 ?</code> (Vorzeichenprüfung nach vorzeichenbehafteter Typkonvertierung)\n</li><li>Aktionszustand <code>DeltaCounter = DeltaCounter + 16</code> (Korrektur des 4-Bit-Zählerüberlaufs)\n</li><li>Zusammenführungsknoten (Merge Node)\n</li><li>Endknoten <code>return</code> (Rückgabe des berechneten <code>DeltaCounter</code>)\n</li><li>Variablen: Eingangsdatum <code>ReceivedCounter</code>, Zustandsdatum <code>State-&gt;LastValidCounter</code>, lokale Variable/Rückgabewert <code>DeltaCounter</code> (vorzeichenbehaftet interpretiert als <code>sint8</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Start wird die Differenz <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> gebildet.\n</li><li>Der resultierende Wert wird als <code>sint8</code> interpretiert und auf einen Wert kleiner als 0 geprüft (<code>(sint8) DeltaCounter &lt; 0 ?</code>).\n</li><li>Bei Erfüllung der Bedingung (<code>[TRUE]</code>) zweigt der Kontrollfluss nach links ab und korrigiert den Zählerwert über <code>DeltaCounter = DeltaCounter + 16</code>.\n</li><li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), bleibt <code>DeltaCounter</code> unverändert.\n</li><li>Beide Pfade laufen im Zusammenführungsknoten zusammen und der Kontrollfluss endet an der Rückgabe (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik dient der Bestimmung des Zählerabstands für E2E-Profile mit 4-Bit-Zähler (Wertebereich 0 bis 15). Software-Entwickler müssen die Typkonvertierung nach <code>sint8</code> zwingend vorzeichenrichtig ausführen, um negative Differenzen bei Wraparound korrekt zu erkennen und durch Addition von 16 in den gültigen positiven Differenzbereich abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c15e1bee3d4c2ded", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Berechnung des Zählerdifferenzwerts (<code>DeltaCounter</code>) bei Empfang einer E2E-geschützten Botschaft innerhalb der AUTOSAR E2E-Protokollspezifikation. Es stellt den normativen Berechnungsalgorithmus inklusive Modulo-16-Überlaufkorrektur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionszustand <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> (Berechnung der Rohdifferenz)\n</li><li>Entscheidungsknoten <code>(sint8) DeltaCounter &lt; 0 ?</code> (Vorzeichenprüfung nach vorzeichenbehafteter Typkonvertierung)\n</li><li>Aktionszustand <code>DeltaCounter = DeltaCounter + 16</code> (Korrektur des 4-Bit-Zählerüberlaufs)\n</li><li>Zusammenführungsknoten (Merge Node)\n</li><li>Endknoten <code>return</code> (Rückgabe des berechneten <code>DeltaCounter</code>)\n</li><li>Variablen: Eingangsdatum <code>ReceivedCounter</code>, Zustandsdatum <code>State-&gt;LastValidCounter</code>, lokale Variable/Rückgabewert <code>DeltaCounter</code> (vorzeichenbehaftet interpretiert als <code>sint8</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Start wird die Differenz <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> gebildet.\n</li><li>Der resultierende Wert wird als <code>sint8</code> interpretiert und auf einen Wert kleiner als 0 geprüft (<code>(sint8) DeltaCounter &lt; 0 ?</code>).\n</li><li>Bei Erfüllung der Bedingung (<code>[TRUE]</code>) zweigt der Kontrollfluss nach links ab und korrigiert den Zählerwert über <code>DeltaCounter = DeltaCounter + 16</code>.\n</li><li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), bleibt <code>DeltaCounter</code> unverändert.\n</li><li>Beide Pfade laufen im Zusammenführungsknoten zusammen und der Kontrollfluss endet an der Rückgabe (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik dient der Bestimmung des Zählerabstands für E2E-Profile mit 4-Bit-Zähler (Wertebereich 0 bis 15). Software-Entwickler müssen die Typkonvertierung nach <code>sint8</code> zwingend vorzeichenrichtig ausführen, um negative Differenzen bei Wraparound korrekt zu erkennen und durch Addition von 16 in den gültigen positiven Differenzbereich abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-03d3d13b355f5998", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Berechnung des Zählerdifferenzwerts (<code>DeltaCounter</code>) bei Empfang einer E2E-geschützten Botschaft innerhalb der AUTOSAR E2E-Protokollspezifikation. Es stellt den normativen Berechnungsalgorithmus inklusive Modulo-16-Überlaufkorrektur dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionszustand <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> (Berechnung der Rohdifferenz)\n</li><li>Entscheidungsknoten <code>(sint8) DeltaCounter &lt; 0 ?</code> (Vorzeichenprüfung nach vorzeichenbehafteter Typkonvertierung)\n</li><li>Aktionszustand <code>DeltaCounter = DeltaCounter + 16</code> (Korrektur des 4-Bit-Zählerüberlaufs)\n</li><li>Zusammenführungsknoten (Merge Node)\n</li><li>Endknoten <code>return</code> (Rückgabe des berechneten <code>DeltaCounter</code>)\n</li><li>Variablen: Eingangsdatum <code>ReceivedCounter</code>, Zustandsdatum <code>State-&gt;LastValidCounter</code>, lokale Variable/Rückgabewert <code>DeltaCounter</code> (vorzeichenbehaftet interpretiert als <code>sint8</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Start wird die Differenz <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> gebildet.\n</li><li>Der resultierende Wert wird als <code>sint8</code> interpretiert und auf einen Wert kleiner als 0 geprüft (<code>(sint8) DeltaCounter &lt; 0 ?</code>).\n</li><li>Bei Erfüllung der Bedingung (<code>[TRUE]</code>) zweigt der Kontrollfluss nach links ab und korrigiert den Zählerwert über <code>DeltaCounter = DeltaCounter + 16</code>.\n</li><li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), bleibt <code>DeltaCounter</code> unverändert.\n</li><li>Beide Pfade laufen im Zusammenführungsknoten zusammen und der Kontrollfluss endet an der Rückgabe (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik dient der Bestimmung des Zählerabstands für E2E-Profile mit 4-Bit-Zähler (Wertebereich 0 bis 15). Software-Entwickler müssen die Typkonvertierung nach <code>sint8</code> zwingend vorzeichenrichtig ausführen, um negative Differenzen bei Wraparound korrekt zu erkennen und durch Addition von 16 in den gültigen positiven Differenzbereich abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0d58b7b08be8d734", "to": "FIG-dce6a37ceea2173d", "fr": "R1.3.0", "tr": "R1.5.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ersetzung des gesamten Kontrollflusses: Berechnung von <code>DeltaCounter</code> (<code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> mit Überlaufkorrektur <code>+ 16</code> bei <code>(sint8) DeltaCounter &lt; 0</code>) statt Inkrementierungs-/Reset-Logik von <code>State-&gt;Counter</code>.\n</li><li>Einführung der Eingangs- und Zustandsvariablen <code>ReceivedCounter</code> und <code>State-&gt;LastValidCounter</code>.\n</li><li>Entfernung der Zähleroperationen <code>State-&gt;Counter ++</code> und <code>State-&gt;Counter = 0</code>.\n</li><li>Ergänzung der Beschriftung <code>return</code> am Endknoten.\n</li></ul>"}, {"from": "FIG-dce6a37ceea2173d", "to": "FIG-0d58b7b08be8d734", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Rücknahme der <code>DeltaCounter</code>-Berechnung zugunsten des Zähler-Inkrementierungs- und Reset-Ablaufs (<code>State-&gt;Counter ++</code> bzw. <code>State-&gt;Counter = 0</code>).\n</li><li>Entfernung der Variablen <code>DeltaCounter</code>, <code>ReceivedCounter</code> und <code>State-&gt;LastValidCounter</code>.\n</li><li>Entfernung der <code>return</code>-Beschriftung am Endknoten.\n</li></ul>"}, {"from": "FIG-dce6a37ceea2173d", "to": "FIG-c15e1bee3d4c2ded", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Typografische Bereinigung am oberen Startknoten: Entfernung des abgeschnittenen Textfragments oberhalb des Initialknotens.\n</li><li>Vertauschung bzw. präzisere Platzierung der Guard-Label an den Zweigen der Verzweigungsraute: Ausrichtung von <code>[TRUE]</code> nach links und <code>[FALSE]</code> nach unten.\n</li></ul>"}, {"from": "FIG-c15e1bee3d4c2ded", "to": "FIG-03d3d13b355f5998", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
